# Intermediate unit 1 – Phrasal verbs: the basics. Bám sách: trang 6–7 (đã xem ảnh trang) + đáp án + Mini dictionary (OCR 300 dpi). Không chép nguyên văn.
# Unit giới thiệu: lý thuyết theo mục A/B của sách; thẻ cho mọi phrasal verb được dạy trên trang và trong bài tập (unit đầu tiên chúng xuất hiện).
theory = (
 H("A", "What are phrasal verbs?", "Phrasal verb là gì?")
 + P("A phrasal verb is a verb plus a particle. The meaning of the whole phrase is often different from the meanings of its parts.", "Phrasal verb gồm một động từ và một tiểu từ. Nghĩa của cả cụm thường khác nghĩa của từng phần.")
 + T([
    ("<b>look up</b>", "find the meaning of new words in a dictionary", "tra nghĩa từ mới trong từ điển"),
    ("<b>go through</b>", "read an application form carefully with someone and discuss it to check it is correct", "đọc kỹ đơn cùng ai và trao đổi để chắc chắn mọi thứ đúng"),
    ("<b>make</b> sb <b>out</b>", "understand someone’s behaviour (the speaker can’t understand Jake)", "hiểu được cách cư xử của ai (người nói không hiểu nổi Jake)"),
 ])
 + P("Particles are short words that also work as prepositions or adverbs – common ones include <i>up, down, in, out, on, off, over, back, away, through, about, around</i>.", "Tiểu từ là những từ ngắn cũng làm giới từ hoặc trạng từ – thường gặp có <i>up, down, in, out, on, off, over, back, away, through, about, around</i>.")
 + H("B", "What do I need to know about phrasal verbs?", "Cần biết gì về phrasal verb?")
 + P("First, learn the meaning of the whole verb as one unit – the Mini dictionary helps. <b>Look up</b> alone has several meanings: search for information, visit someone you haven’t seen for a long time, and improve (things are looking up).", "Trước hết, học nghĩa của cả cụm như một đơn vị – Mini dictionary sẽ giúp. Riêng <b>look up</b> đã có nhiều nghĩa: tra cứu thông tin, ghé thăm người lâu không gặp, và khá lên (mọi chuyện đang khá lên).")
 + P("Next, learn the grammar pattern (<i>sth</i> = something, <i>sb</i> = someone):", "Tiếp theo, học dạng ngữ pháp (<i>sth</i> = something, <i>sb</i> = someone):")
 + table(["Pattern", "What it shows", "Example in the book"], ["Dạng", "Ý nghĩa", "Ví dụ trong sách"], [
    ("<b>eat out</b>", "", "no object", "không có tân ngữ", "too tired to cook, so they ate in a restaurant", "quá mệt để nấu nên đi ăn nhà hàng"),
    ("<b>bring back</b> sth", "", "non-human object only", "tân ngữ chỉ là vật", "a photo brings back happy memories", "bức ảnh gợi lại kỷ niệm đẹp"),
    ("<b>ask</b> sb <b>out</b>", "", "human object only", "tân ngữ chỉ là người", "invite Poppy to the cinema or a restaurant", "mời Poppy đi xem phim hay đi ăn"),
    ("<b>look after</b> sb/sth", "", "object human or not; it comes after the particle", "tân ngữ là người hoặc vật; đứng sau tiểu từ", "the baby, the plants, the cat", "em bé, cây cảnh, con mèo"),
    ("<b>ring</b> sb <b>back</b>", "", "object must come before the particle", "tân ngữ bắt buộc đứng trước tiểu từ", "I’ll phone you again later", "lát tôi gọi lại cho bạn"),
    ("<b>drop off</b> sb/sth", "", "object before or after the particle", "tân ngữ đứng trước hoặc sau tiểu từ", "deliver a present to her house", "để quà ở nhà cô ấy"),
 ])
 + NOTE("<b>Exercise 1.4</b>: some phrasal verbs are followed by a fixed preposition (three-part verbs): <i>look forward to</i>, <i>go out with</i>, <i>look down on</i>, <i>do away with</i>, <i>come up against</i>, <i>get away with</i>, <i>put up with</i>. Learn the preposition together with the verb.",
        "<b>Bài 1.4</b>: một số phrasal verb đi kèm giới từ cố định (động từ ba thành phần): <i>look forward to</i>, <i>go out with</i>, <i>look down on</i>, <i>do away with</i>, <i>come up against</i>, <i>get away with</i>, <i>put up with</i>. Hãy học giới từ cùng với động từ.")
)
def PV(word, pos, reg, d_en, ipa, d_vi, gl, ex_en, ex_vi, gram, note, coll, mist, syn, ant, sense=""):
    return I(word, pos, reg, d_en, ipa, d_vi, gl, ex_en, ex_vi, G(word, pos, gl, gram, note, coll, reg, mist), syn, ant, sense=sense)
